105→    }
106→
107→    #[test]
108→    fn test_deserialize_short_blob_errors() {
109→        assert!(deserialize_vault_blob_v2(&[0x02, 0x00]).is_err());
110→    }
111→
112→    #[test]
113→    fn test_key_len_overflow_errors() {
114→        let blob = vec![0x02, 0x03, 0xE8, 0, 0, 0, 0, 0];
115→        assert!(deserialize_vault_blob_v2(&blob).is_err());
116→    }
117→
118→    #[test]
119→    fn test_header_format() {
120→        let key = vec![0xBB; 129];
121→        let blob = serialize_vault_blob_v2(&key).unwrap();
122→        assert_eq!(blob[0], 0x02);
123→        assert_eq!(blob[1], 0x00); // 129 >> 8 = 0
124→        assert_eq!(blob[2], 0x81); // 129 & 0xFF = 0x81
125→        assert_eq!(&blob[3..], key.as_slice());
126→        assert_eq!(blob.len(), 3 + 129);
127→    }
128→
129→    // Cross-platform test vector: MUST match TypeScript vault-blob-vectors.test.ts
130→    // Key (129 bytes): 0xAA followed by 128 bytes incrementing 0x00..0x7F
131→    // Expected hex: 02 0081 aa 0001...7f (key only, no metadata)
132→    #[test]
133→    fn test_cross_platform_vector() {
134→        let mut key = vec![0xAA];
135→        for i in 0u8..128 {
136→            key.push(i);
137→        }
138→        assert_eq!(key.len(), 129);
139→
140→        let blob = serialize_vault_blob_v2(&key).unwrap();
141→
142→        assert_eq!(blob[0], 0x02);
143→        assert_eq!(blob[1], 0x00);
144→        assert_eq!(blob[2], 0x81); // 129
145→        assert_eq!(blob.len(), 3 + 129);
146→
147→        let blob_hex = hex::encode(&blob);
148→        let expected_hex = concat!(
149→            "02",   // version byte
150→            "0081", // key_len = 129
151→            "aa",   // key[0]
152→            "000102030405060708090a0b0c0d0e0f", // key[1..16]
153→            "101112131415161718191a1b1c1d1e1f", // key[17..32]
154→            "202122232425262728292a2b2c2d2e2f", // key[33..48]
155→            "303132333435363738393a3b3c3d3e3f", // key[49..64]
156→            "404142434445464748494a4b4c4d4e4f", // key[65..80]
157→            "505152535455565758595a5b5c5d5e5f", // key[81..96]
158→            "606162636465666768696a6b6c6d6e6f", // key[97..112]
159→            "707172737475767778797a7b7c7d7e7f", // key[113..128]
160→        );
161→        assert_eq!(blob_hex, expected_hex);
162→
163→        let dk = deserialize_vault_blob_v2(&blob).unwrap();
164→        assert_eq!(dk, key.as_slice());
165→    }
166→
167→    // Cross-platform test vector 2: minimal blob (1-byte key)
168→    #[test]
169→    fn test_cross_platform_minimal_vector() {
170→        let key = vec![0xFF];
171→        let blob = serialize_vault_blob_v2(&key).unwrap();
172→        let expected_hex = "020001ff";
173→        assert_eq!(hex::encode(&blob), expected_hex);
174→
175→        let dk = deserialize_vault_blob_v2(&blob).unwrap();
176→        assert_eq!(dk, &[0xFF]);
177→    }
178→
179→    #[test]
180→    fn test_key_too_long_for_u16() {
181→        let key = vec![0xAA; 65536];
182→        let result = serialize_vault_blob_v2(&key);
183→        assert!(result.is_err());
184→        assert!(result.unwrap_err().contains("too long"));
185→    }
186→
187→    #[test]
188→    fn test_zero_length_key_rejected() {
189→        let result = serialize_vault_blob_v2(&[]);
190→        assert!(result.is_err());
191→        assert!(result.unwrap_err().contains("must not be empty"));
192→
193→        let blob = vec![0x02, 0x00, 0x00];
194→        assert!(deserialize_vault_blob_v2(&blob).is_err());
195→    }
196→}
