 1→//! IPFS content operations via the CipherBox backend API.
 2→//!
 3→//! Provides fetching encrypted file content and uploading encrypted files.
 4→//! Content is always encrypted -- the backend never sees plaintext.
 5→
 6→use super::client::ApiClient;
 7→
 8→/// Fetch encrypted file content from IPFS via the backend.
 9→///
10→/// GET /ipfs/{cid} returns raw encrypted bytes (application/octet-stream).
11→pub async fn fetch_content(client: &ApiClient, cid: &str) -> Result<Vec<u8>, String> {
12→    let resp = client
13→        .authenticated_get(&format!("/ipfs/{}", cid))
14→        .await
15→        .map_err(|e| format!("IPFS fetch failed: {}", e))?;
16→
17→    if !resp.status().is_success() {
18→        let status = resp.status();
19→        let body = resp.text().await.unwrap_or_default();
20→        return Err(format!("IPFS fetch failed ({}): {}", status, body));
21→    }
22→
23→    let bytes = resp
24→        .bytes()
25→        .await
26→        .map_err(|e| format!("Failed to read IPFS response: {}", e))?;
27→    Ok(bytes.to_vec())
28→}
29→
30→/// Upload encrypted file content to IPFS via the backend.
31→///
32→/// POST /ipfs/upload with multipart form data. Returns CID string.
33→/// Used by write operations in plan 09-06.
34→pub async fn upload_content(client: &ApiClient, data: &[u8]) -> Result<String, String> {
35→    use reqwest::multipart;
36→
37→    let part = multipart::Part::bytes(data.to_vec())
38→        .file_name("encrypted")
39→        .mime_str("application/octet-stream")
40→        .map_err(|e| format!("Failed to create multipart part: {}", e))?;
41→
42→    let form = multipart::Form::new().part("file", part);
43→
44→    // We need a raw request for multipart -- use authenticated_multipart_post
45→    // For now, use the client's underlying reqwest client via get_bytes pattern
46→    // The upload endpoint is /ipfs/upload
47→    let resp = client
48→        .authenticated_multipart_post("/ipfs/upload", form)
49→        .await
50→        .map_err(|e| format!("IPFS upload failed: {}", e))?;
51→
52→    if !resp.status().is_success() {
53→        let status = resp.status();
54→        let body = resp.text().await.unwrap_or_default();
55→        return Err(format!("IPFS upload failed ({}): {}", status, body));
56→    }
57→
58→    #[derive(serde::Deserialize)]
59→    struct UploadResponse {
60→        cid: String,
61→    }
62→
63→    let upload_resp: UploadResponse = resp
64→        .json()
65→        .await
66→        .map_err(|e| format!("Failed to parse upload response: {}", e))?;
67→
68→    Ok(upload_resp.cid)
69→}
