1104→/// Generate a UUID-like string from an inode number (deterministic).
1105→/// Used for folder/file IDs in metadata when we don't have the original UUID.
1106→#[cfg(any(feature = "fuse", feature = "winfsp"))]
1107→fn uuid_from_ino(ino: u64) -> String {
1108→    format!(
1109→        "{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}",
1110→        (ino >> 32) as u32,
1111→        ((ino >> 16) & 0xFFFF) as u16,
1112→        (ino & 0xFFF) as u16,
1113→        (0x8000 | (ino & 0x3FFF)) as u16,
1114→        ino & 0xFFFFFFFFFFFF,
1115→    )
1116→}
