1118→/// Get the mount point path: ~/CipherBox
1119→#[cfg(any(feature = "fuse", feature = "winfsp"))]
1120→pub fn mount_point() -> PathBuf {
1121→    dirs::home_dir()
1122→        .expect("Could not determine home directory")
1123→        .join("CipherBox")
1124→}
1125→
1126→/// Mount the FUSE filesystem after successful authentication (macOS only).
1127→///
1128→/// Creates the ~/CipherBox directory if it doesn't exist, builds the
1129→/// CipherBoxFS with keys from AppState, and spawns the FUSE event loop
1130→/// on a dedicated std::thread (not tokio -- fuser runs its own event loop).
1131→///
1132→/// Returns a JoinHandle for the mount thread.
1133→#[cfg(feature = "fuse")]
1134→pub async fn mount_filesystem(
1135→    state: &AppState,
1136→    rt: tokio::runtime::Handle,
1137→    private_key: Vec<u8>,
1138→    public_key: Vec<u8>,
1139→    root_folder_key: Vec<u8>,
1140→    root_ipns_name: String,
1141→    root_ipns_private_key: Option<Vec<u8>>,
1142→    tee_public_key: Option<Vec<u8>>,
1143→    tee_key_epoch: Option<u32>,
1144→) -> Result<std::thread::JoinHandle<()>, String> {
1145→    let mount_path = mount_point();
1146→
1147→    // Refuse to proceed if mount point is a symlink (TOCTOU defense)
1148→    if mount_path.is_symlink() {
1149→        return Err("Mount point is a symlink — refusing to proceed".to_string());
1150→    }
1151→
1152→    // Create mount directory if it doesn't exist
1153→    if !mount_path.exists() {
1154→        std::fs::create_dir_all(&mount_path)
1155→            .map_err(|e| format!("Failed to create mount point: {}", e))?;
1156→        #[cfg(unix)]
1157→        {
1158→            use std::os::unix::fs::PermissionsExt;
1159→            let _ = std::fs::set_permissions(&mount_path, std::fs::Permissions::from_mode(0o700));
1160→        }
1161→    } else {
1162→        // Clean stale files left after a crash (e.g. .DS_Store, .metadata_never_index).
1163→        // FUSE mount will fail or behave unexpectedly if the directory isn't empty.
1164→        if let Ok(entries) = std::fs::read_dir(&mount_path) {
1165→            for entry in entries.flatten() {
1166→                let path = entry.path();
1167→                if path.is_dir() {
1168→                    let _ = std::fs::remove_dir_all(&path);
1169→                } else {
1170→                    let _ = std::fs::remove_file(&path);
1171→                }
1172→            }
1173→            log::info!("Cleaned stale mount point: {}", mount_path.display());
1174→        }
1175→    }
1176→
1177→    // Prevent Spotlight from indexing the mount (macOS only)
1178→    #[cfg(target_os = "macos")]
1179→    {
1180→        let never_index = mount_path.join(".metadata_never_index");
1181→        if !never_index.exists() {
1182→            let _ = std::fs::File::create(&never_index);
1183→        }
1184→    }
1185→
1186→    // Create temp directory for write buffering
1187→    let temp_dir = std::env::temp_dir().join("cipherbox");
1188→    std::fs::create_dir_all(&temp_dir)
1189→        .map_err(|e| format!("Failed to create temp directory: {}", e))?;
1190→    #[cfg(unix)]
1191→    {
1192→        use std::os::unix::fs::PermissionsExt;
1193→        let _ = std::fs::set_permissions(&temp_dir, std::fs::Permissions::from_mode(0o700));
1194→    }
1195→
1196→    // Build the filesystem
1197→    let mut inodes = inode::InodeTable::new();
1198→
1199→    // Set root inode's IPNS data
1200→    if let Some(root) = inodes.get_mut(inode::ROOT_INO) {
1201→        root.kind = inode::InodeKind::Root {
1202→            ipns_private_key: root_ipns_private_key.map(Zeroizing::new),
1203→            ipns_name: Some(root_ipns_name.clone()),
1204→        };
1205→    }
1206→
1207→    // Channels for background operations
1208→    let (refresh_tx, refresh_rx) = std::sync::mpsc::channel::<PendingRefresh>();
1209→    let (content_tx, content_rx) = std::sync::mpsc::channel::<PendingContent>();
1210→    let (upload_tx, upload_rx) = std::sync::mpsc::channel::<UploadComplete>();
1211→
1212→    // Pre-populate root folder BEFORE mounting so init()/readdir() have no network I/O.
1213→    // This runs on the calling thread (tokio context available via rt handle).
1214→    let mut metadata_cache = cache::MetadataCache::new();
1215→    log::info!("Pre-populating root folder from IPNS...");
1216→    let fetch_result: Result<(Vec<u8>, String), String> = async {
1217→        let resolve_resp =
1218→            crate::api::ipns::resolve_ipns(&state.api, &root_ipns_name).await?;
1219→        let encrypted_bytes =
1220→            crate::api::ipfs::fetch_content(&state.api, &resolve_resp.cid).await?;
1221→        Ok((encrypted_bytes, resolve_resp.cid))
1222→    }.await;
1223→    match fetch_result {
1224→        Ok((encrypted_bytes, cid)) => {
1225→            match decrypt::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &root_folder_key) {
1226→                Ok(metadata) => {
1227→                    // Cache metadata directly for readdir staleness checks
1228→                    metadata_cache.set(&root_ipns_name, metadata.clone(), cid);
1229→
1230→                    // Populate inode table -- initial mount, full replace
1231→                    match inodes.populate_folder(inode::ROOT_INO, &metadata, &private_key, &public_key, false) {
1232→                        Ok(()) => {
1233→                            log::info!("Root folder pre-populated successfully");
1234→
1235→                            // Resolve FilePointers eagerly before mount
1236→                            let unresolved = inodes.get_unresolved_file_pointers();
1237→                            if !unresolved.is_empty() {
1238→                                log::info!("Resolving {} root FilePointer(s)...", unresolved.len());
1239→                                let root_folder_key_arr: Result<[u8; 32], _> = root_folder_key.as_slice().try_into();
1240→                                if let Ok(fk) = root_folder_key_arr {
1241→                                    for (fp_ino, fp_ipns) in &unresolved {
1242→                                        let fp_result: Result<Vec<u8>, String> = async {
1243→                                            let resp = crate::api::ipns::resolve_ipns(&state.api, fp_ipns).await?;
1244→                                            let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
1245→                                            Ok(bytes)
1246→                                        }.await;
1247→                                        match fp_result {
1248→                                            Ok(enc_bytes) => {
1249→                                                match decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk) {
1250→                                                    Ok(fm) => {
1251→                                                        inodes.resolve_file_pointer(
1252→                                                            *fp_ino, fm.cid, fm.file_key_encrypted,
1253→                                                            fm.file_iv, fm.size, fm.encryption_mode,
1254→                                                            fm.versions,
1255→                                                        );
1256→                                                    }
1257→                                                    Err(e) => log::warn!("Root FilePointer decrypt failed for ino {}: {}", fp_ino, e),
1258→                                                }
1259→                                            }
1260→                                            Err(e) => log::warn!("Root FilePointer resolve failed for ino {}: {}", fp_ino, e),
1261→                                        }
1262→                                    }
1263→                                }
1264→                            }
1265→                        }
1266→                        Err(e) => log::warn!("Root folder populate failed: {}", e),
1267→                    }
1268→
1269→                    // Pre-populate immediate subfolders so Finder's first READDIR
1270→                    // returns correct data. NFS clients cache READDIR aggressively
1271→                    // and won't re-fetch even when mtime changes, so returning empty
1272→                    // on first access causes permanently stale Finder listings.
1273→                    let subfolder_infos: Vec<(u64, String, Zeroizing<Vec<u8>>)> = inodes
1274→                        .inodes
1275→                        .values()
1276→                        .filter_map(|inode| {
1277→                            if inode.parent_ino != inode::ROOT_INO { return None; }
1278→                            if let inode::InodeKind::Folder { ref ipns_name, ref folder_key, .. } = inode.kind {
1279→                                Some((inode.ino, ipns_name.clone(), folder_key.clone()))
1280→                            } else {
1281→                                None
1282→                            }
1283→                        })
1284→                        .collect();
1285→
1286→                    for (sub_ino, sub_ipns, sub_key) in &subfolder_infos {
1287→                        log::info!("Pre-populating subfolder ino={} ipns={}", sub_ino, sub_ipns);
1288→                        let sub_result: Result<(Vec<u8>, String), String> = async {
1289→                            let resp = crate::api::ipns::resolve_ipns(&state.api, sub_ipns).await?;
1290→                            let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
1291→                            Ok((bytes, resp.cid))
1292→                        }.await;
1293→                        match sub_result {
1294→                            Ok((enc_bytes, sub_cid)) => {
1295→                                match decrypt::decrypt_metadata_from_ipfs_public(&enc_bytes, sub_key) {
1296→                                    Ok(sub_metadata) => {
1297→                                        metadata_cache.set(sub_ipns, sub_metadata.clone(), sub_cid);
1298→                                        match inodes.populate_folder(*sub_ino, &sub_metadata, &private_key, &public_key, false) {
1299→                                            Ok(()) => {
1300→                                                log::info!("Subfolder ino={} pre-populated", sub_ino);
1301→                                                // Resolve FilePointers in subfolder
1302→                                                let sub_unresolved = inodes.get_unresolved_file_pointers();
1303→                                                if !sub_unresolved.is_empty() {
1304→                                                    let sk_arr: Result<[u8; 32], _> = sub_key.as_slice().try_into();
1305→                                                    if let Ok(sk) = sk_arr {
1306→                                                        for (fp_ino, fp_ipns) in &sub_unresolved {
1307→                                                            let fp_result: Result<Vec<u8>, String> = async {
1308→                                                                let resp = crate::api::ipns::resolve_ipns(&state.api, fp_ipns).await?;
1309→                                                                let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
1310→                                                                Ok(bytes)
1311→                                                            }.await;
1312→                                                            match fp_result {
1313→                                                                Ok(enc_bytes) => {
1314→                                                                    match decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &sk) {
1315→                                                                        Ok(fm) => {
1316→                                                                            inodes.resolve_file_pointer(
1317→                                                                                *fp_ino, fm.cid, fm.file_key_encrypted,
1318→                                                                                fm.file_iv, fm.size, fm.encryption_mode,
1319→                                                                                fm.versions,
1320→                                                                            );
1321→                                                                        }
1322→                                                                        Err(e) => log::warn!("Sub FilePointer decrypt failed: {}", e),
1323→                                                                    }
1324→                                                                }
1325→                                                                Err(e) => log::warn!("Sub FilePointer resolve failed: {}", e),
1326→                                                            }
1327→                                                        }
1328→                                                    }
1329→                                                }
1330→                                            }
1331→                                            Err(e) => log::warn!("Subfolder ino={} populate failed: {}", sub_ino, e),
1332→                                        }
1333→                                    }
1334→                                    Err(e) => log::warn!("Subfolder ino={} decrypt failed: {}", sub_ino, e),
1335→                                }
1336→                            }
1337→                            Err(e) => log::warn!("Subfolder ino={} fetch failed: {}", sub_ino, e),
1338→                        }
1339→                    }
1340→                }
1341→                Err(e) => log::warn!("Root metadata decryption failed: {}", e),
1342→            }
1343→        }
1344→        Err(e) => log::warn!("Root folder fetch failed (mount will show empty): {}", e),
1345→    }
1346→
1347→    let fs = CipherBoxFS {
1348→        inodes,
1349→        metadata_cache,
1350→        content_cache: cache::ContentCache::new(),
1351→        api: state.api.clone(),
1352→        private_key: Zeroizing::new(private_key),
1353→        public_key: Zeroizing::new(public_key),
1354→        root_folder_key: Zeroizing::new(root_folder_key),
1355→        root_ipns_name,
1356→        rt,
1357→        next_fh: AtomicU64::new(1),
1358→        open_files: HashMap::new(),
1359→        temp_dir,
1360→        tee_public_key,
1361→        tee_key_epoch,
1362→        refresh_rx,
1363→        refresh_tx,
1364→        prefetching: std::collections::HashSet::new(),
1365→        content_rx,
1366→        content_tx,
1367→        pending_content: HashMap::new(),
1368→        upload_rx,
1369→        upload_tx,
1370→        mutated_folders: HashMap::new(),
1371→        publish_coordinator: Arc::new(PublishCoordinator::new()),
1372→        publish_queue: HashMap::new(),
1373→    };
1374→
1375→    let mount_path_clone = mount_path.clone();
1376→
1377→    // Mount options — platform-specific.
1378→    // Linux: kernel FUSE supports AutoUnmount and DefaultPermissions natively.
1379→    // macOS: FUSE-T (NFS/SMB proxy) requires custom options; AutoUnmount and
1380→    // DefaultPermissions are not supported.
1381→    // Linux: kernel FUSE with libfuse3. We skip AutoUnmount because it
1382→    // requires allow_other/allow_root, which in turn needs user_allow_other
1383→    // in /etc/fuse.conf — an extra config step we don't want to impose.
1384→    // Instead, unmount_filesystem() calls fusermount3 -u directly.
1385→    #[cfg(target_os = "linux")]
1386→    let options = vec![
1387→        MountOption::FSName("CipherBox".to_string()),
1388→        MountOption::DefaultPermissions,
1389→        MountOption::RW,
1390→    ];
1391→
1392→    #[cfg(target_os = "macos")]
1393→    let options = vec![
1394→        // FUSE-T mount options:
1395→        // - backend=smb: Use SMB instead of NFS backend. NFS has a known macOS kernel
1396→        //   bug where WRITE RPCs never reach the FUSE-T server for newly created files,
1397→        //   causing permanent process hangs. SMB backend avoids this entirely.
1398→        MountOption::FSName("CipherBox".to_string()),
1399→        MountOption::CUSTOM("volname=CipherBox".to_string()),
1400→        MountOption::CUSTOM("noappledouble".to_string()),
1401→        MountOption::CUSTOM("noapplexattr".to_string()),
1402→        MountOption::CUSTOM("backend=smb".to_string()),
1403→        MountOption::RW,
1404→    ];
1405→
1406→    // Spawn FUSE event loop on a dedicated OS thread (not tokio).
1407→    // Use a channel so the thread can signal back if mount2 fails immediately
1408→    // (e.g. macFUSE kext not loaded). If mount2 succeeds, it blocks until
1409→    // unmount and never sends on the channel, so we use a recv_timeout.
1410→    let (tx, rx) = std::sync::mpsc::sync_channel::<Result<(), String>>(1);
1411→
1412→    let handle = std::thread::Builder::new()
1413→        .name("fuse-mount".to_string())
1414→        .spawn(move || {
1415→            log::info!(
1416→                "Mounting CipherBoxFS at {}",
1417→                mount_path_clone.display()
1418→            );
1419→            match fuser::mount2(fs, &mount_path_clone, &options) {
1420→                Ok(()) => {
1421→                    log::info!("FUSE filesystem unmounted cleanly");
1422→                    let _ = tx.send(Ok(()));
1423→                }
1424→                Err(e) => {
1425→                    log::error!("FUSE mount error: {}", e);
1426→                    let _ = tx.send(Err(format!("FUSE mount error: {}", e)));
1427→                }
1428→            }
1429→        })
1430→        .map_err(|e| format!("Failed to spawn FUSE thread: {}", e))?;
1431→
1432→    // Wait up to 2 seconds for the mount to either fail or stabilize.
1433→    // If mount2 fails (e.g. missing kext), the error arrives quickly.
1434→    // If mount2 succeeds, it blocks (running the event loop) and we get a timeout.
1435→    match rx.recv_timeout(std::time::Duration::from_secs(2)) {
1436→        Ok(Ok(())) => {
1437→            // Filesystem was unmounted immediately (unusual)
1438→            Err("FUSE filesystem unmounted immediately after mounting".to_string())
1439→        }
1440→        Ok(Err(e)) => {
1441→            // Mount failed — propagate the error
1442→            Err(e)
1443→        }
1444→        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
1445→            // No response after 2s — mount is running
1446→            log::info!("FUSE mount confirmed at {}", mount_path.display());
1447→            Ok(handle)
1448→        }
1449→        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
1450→            Err("FUSE mount thread exited unexpectedly".to_string())
1451→        }
1452→    }
1453→}
1454→
1455→/// Unmount the FUSE filesystem (macOS only).
1456→///
1457→/// Calls the system `umount` command to cleanly unmount ~/CipherBox.
1458→#[cfg(all(feature = "fuse", target_os = "macos"))]
1459→pub fn unmount_filesystem() -> Result<(), String> {
1460→    let mount_path = mount_point();
1461→    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());
1462→
1463→    // Clean up temp directory
1464→    let temp_dir = std::env::temp_dir().join("cipherbox");
1465→    if temp_dir.exists() {
1466→        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
1467→            log::warn!("Failed to clean temp directory: {}", e);
1468→        }
1469→    }
1470→
1471→    let status = std::process::Command::new("umount")
1472→        .arg(mount_path.to_str().unwrap())
1473→        .status()
1474→        .map_err(|e| format!("Failed to run umount: {}", e))?;
1475→
1476→    if status.success() {
1477→        log::info!("FUSE filesystem unmounted successfully");
1478→        Ok(())
1479→    } else {
1480→        // Try diskutil unmount force as fallback on macOS — Finder keeps handles open
1481→        log::info!("umount failed (likely busy), trying diskutil unmount force");
1482→        let status = std::process::Command::new("diskutil")
1483→            .args(["unmount", "force", mount_path.to_str().unwrap()])
1484→            .status()
1485→            .map_err(|e| format!("Failed to run diskutil unmount force: {}", e))?;
1486→
1487→        if status.success() {
1488→            log::info!("FUSE filesystem force-unmounted via diskutil");
1489→            Ok(())
1490→        } else {
1491→            Err(format!(
1492→                "Failed to unmount {} — close Finder windows and retry",
1493→                mount_path.display()
1494→            ))
1495→        }
1496→    }
1497→}
