//! Error types for the CipherBox API client.

use thiserror::Error;

/// Errors that can occur when communicating with the CipherBox API.
#[derive(Debug, Error)]
pub enum ApiError {
    /// HTTP request failed at the transport level.
    #[error("HTTP request failed: {0}")]
    RequestFailed(#[from] reqwest::Error),

    /// API returned a non-success status code.
    #[error("API returned error {status}: {message}")]
    ApiResponse {
        /// HTTP status code.
        status: u16,
        /// Error message from the response body.
        message: String,
    },

    /// Authentication failed (401 or token refresh failure).
    #[error("Authentication failed: {0}")]
    AuthFailed(String),

    /// Response body could not be deserialized.
    #[error("Deserialization failed: {0}")]
    DeserializationFailed(String),

    /// IPNS name was not found (404 on resolve).
    #[error("IPNS name not found: {0}")]
    IpnsNotFound(String),
}

//! HTTP client with auth header injection and desktop client type header.
//!
//! All requests include `X-Client-Type: desktop` header so the backend
//! returns refresh tokens in the response body instead of cookies.

use reqwest::{Client, Response};
use serde::Serialize;
use std::sync::Arc;
use tokio::sync::RwLock;

use crate::error::ApiError;

/// HTTP client wrapper for CipherBox API communication.
///
/// Manages base URL, access token, and ensures all requests
/// include the `X-Client-Type: desktop` header.
pub struct ApiClient {
    client: Client,
    base_url: String,
    access_token: Arc<RwLock<Option<String>>>,
}

impl ApiClient {
    /// Create a new API client with the given base URL.
    pub fn new(base_url: &str) -> Self {
        let client = Client::builder()
            .timeout(std::time::Duration::from_secs(120))
            .connect_timeout(std::time::Duration::from_secs(10))
            .build()
            .expect("failed to initialize HTTP client");
        Self {
            client,
            base_url: base_url.trim_end_matches('/').to_string(),
            access_token: Arc::new(RwLock::new(None)),
        }
    }

    /// Store the access token for authenticated requests.
    pub async fn set_access_token(&self, token: String) {
        let mut guard = self.access_token.write().await;
        *guard = Some(token);
    }

    /// Read the current access token (used for session restore).
    pub async fn get_access_token(&self) -> Option<String> {
        self.access_token.read().await.clone()
    }

    /// Clear the access token (used on logout).
    pub async fn clear_access_token(&self) {
        let mut guard = self.access_token.write().await;
        *guard = None;
    }

    /// Send an authenticated GET request to a relative API path.
    pub async fn authenticated_get(&self, path: &str) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        let token = self.access_token.read().await;

        let mut builder = self
            .client
            .get(&url)
            .header("X-Client-Type", "desktop");

        if let Some(ref t) = *token {
            builder = builder.bearer_auth(t);
        }

        Ok(builder.send().await?)
    }

    /// Send an authenticated POST request with a JSON body to a relative API path.
    pub async fn authenticated_post<T: Serialize>(
        &self,
        path: &str,
        body: &T,
    ) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        let token = self.access_token.read().await;

        let mut builder = self
            .client
            .post(&url)
            .header("X-Client-Type", "desktop")
            .json(body);

        if let Some(ref t) = *token {
            builder = builder.bearer_auth(t);
        }

        Ok(builder.send().await?)
    }

    /// Send an unauthenticated POST request with a JSON body to a relative API path.
    /// Used for login and refresh where no access token is available yet.
    pub async fn post<T: Serialize>(
        &self,
        path: &str,
        body: &T,
    ) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        Ok(self
            .client
            .post(&url)
            .header("X-Client-Type", "desktop")
            .json(body)
            .send()
            .await?)
    }

    /// Fetch raw bytes from an absolute URL (used for IPFS content fetching).
    pub async fn get_bytes(&self, url: &str) -> Result<Vec<u8>, ApiError> {
        let resp = self.client.get(url).send().await?;
        let bytes = resp.bytes().await?;
        Ok(bytes.to_vec())
    }

    /// Send an authenticated multipart POST request (used for IPFS file uploads).
    pub async fn authenticated_multipart_post(
        &self,
        path: &str,
        form: reqwest::multipart::Form,
    ) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        let token = self.access_token.read().await;

        let mut builder = self
            .client
            .post(&url)
            .header("X-Client-Type", "desktop")
            .multipart(form);

        if let Some(ref t) = *token {
            builder = builder.bearer_auth(t);
        }

        Ok(builder.send().await?)
    }
}

//! Request and response types for the CipherBox backend API.
//!
//! All structs use camelCase serialization to match the API's JSON format.
//! Auth DTOs use manual Debug impls to redact sensitive fields.

use std::fmt;

use serde::{Deserialize, Serialize};

/// Login request body sent to POST /auth/login.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LoginRequest {
    pub id_token: String,
    pub public_key: String,
    pub login_type: String,
}

impl fmt::Debug for LoginRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("LoginRequest")
            .field("id_token", &"[REDACTED]")
            .field("public_key", &"[REDACTED]")
            .field("login_type", &self.login_type)
            .finish()
    }
}

/// Login response from POST /auth/login (desktop client receives refreshToken in body).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LoginResponse {
    pub access_token: String,
    pub refresh_token: String,
    pub is_new_user: bool,
}

impl fmt::Debug for LoginResponse {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("LoginResponse")
            .field("access_token", &"[REDACTED]")
            .field("refresh_token", &"[REDACTED]")
            .field("is_new_user", &self.is_new_user)
            .finish()
    }
}

/// Refresh request body sent to POST /auth/refresh.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RefreshRequest {
    pub refresh_token: String,
}

impl fmt::Debug for RefreshRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RefreshRequest")
            .field("refresh_token", &"[REDACTED]")
            .finish()
    }
}

/// Refresh response from POST /auth/refresh (desktop client receives refreshToken in body).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RefreshResponse {
    pub access_token: String,
    pub refresh_token: String,
}

impl fmt::Debug for RefreshResponse {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RefreshResponse")
            .field("access_token", &"[REDACTED]")
            .field("refresh_token", &"[REDACTED]")
            .finish()
    }
}

/// TEE public keys included in vault response.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TeeKeysResponse {
    pub current_epoch: u32,
    pub current_public_key: String,
    pub previous_epoch: Option<u32>,
    pub previous_public_key: Option<String>,
}

/// Request body for POST /vault/init (new user vault initialization).
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct InitVaultRequest {
    pub owner_public_key: String,
    pub root_ipns_name: String,
}

impl fmt::Debug for InitVaultRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("InitVaultRequest")
            .field("owner_public_key", &"[REDACTED]")
            .field("root_ipns_name", &self.root_ipns_name)
            .finish()
    }
}

/// Vault response from GET /vault.
///
/// The rootFolderKey lives exclusively in the IPFS vault blob v2 header.
/// The IPNS key is HKDF-derived client-side.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VaultResponse {
    pub root_ipns_name: String,
    pub tee_keys: Option<TeeKeysResponse>,
}

impl fmt::Debug for VaultResponse {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("VaultResponse")
            .field("root_ipns_name", &self.root_ipns_name)
            .field("tee_keys", &self.tee_keys)
            .finish()
    }
}

/// Response from GET /ipns/resolve.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct IpnsResolveResponse {
    /// Whether the resolution succeeded.
    pub success: bool,
    /// CID that the IPNS name currently points to.
    pub cid: String,
    /// Current sequence number as a string (bigint from backend).
    pub sequence_number: String,
}

/// IPNS publish request body matching the backend PublishIpnsDto.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct IpnsPublishRequest {
    /// IPNS name (k51... CIDv1 format).
    pub ipns_name: String,
    /// Base64-encoded marshaled IPNS record (protobuf bytes).
    pub record: String,
    /// CID of the encrypted metadata this record points to.
    pub metadata_cid: String,
    /// Hex-encoded ECIES-wrapped Ed25519 private key for TEE republishing
    /// (only required on first publish for a new folder).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub encrypted_ipns_private_key: Option<String>,
    /// TEE key epoch (required with encrypted_ipns_private_key).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub key_epoch: Option<u32>,
    /// Expected sequence number for optimistic concurrency control.
    /// If set, the server returns 409 Conflict if the current sequence
    /// does not match. Omit to perform an unconditional publish.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expected_sequence_number: Option<String>,
}

/// Result of an IPNS publish attempt.
#[derive(Debug)]
pub enum PublishResult {
    /// Publish succeeded.
    Success,
    /// Server returned 409 Conflict -- another device published since our last sync.
    Conflict {
        /// The server's current sequence number (string, bigint).
        current_sequence_number: String,
    },
}

/// Response from POST /ipfs/upload.
#[derive(Debug, Deserialize)]
pub struct UploadResponse {
    /// CID of the uploaded content.
    pub cid: String,
}

/// Request body for POST /ipfs/unpin.
#[derive(Debug, Serialize)]
pub struct UnpinRequest<'a> {
    /// CID to unpin.
    pub cid: &'a str,
}

//! Folder metadata types and encryption.
//!
//! Matches the TypeScript `FolderMetadata` type exactly.
//! Uses Serde `rename_all = "camelCase"` to produce JSON field names
//! identical to the TypeScript format.
//!
//! Only v2 schema (per-file IPNS pointers via FilePointer) is supported.
//! v1 (inline file data) has been removed.

use serde::{Deserialize, Serialize};
use thiserror::Error;
use zeroize::Zeroize;

use cipherbox_crypto::aes;
use cipherbox_crypto::error::CryptoError;

#[derive(Debug, Error)]
pub enum FolderError {
    #[error("Encryption failed")]
    EncryptionFailed(#[from] CryptoError),
    #[error("Serialization failed")]
    SerializationFailed,
    #[error("Deserialization failed")]
    DeserializationFailed,
}

/// Subfolder entry within folder metadata.
/// Contains ECIES-wrapped keys for accessing the subfolder.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FolderEntry {
    /// UUID for internal reference.
    pub id: String,
    /// Folder name (plaintext, since whole metadata is encrypted).
    pub name: String,
    /// IPNS name for this subfolder (k51... format).
    pub ipns_name: String,
    /// Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata.
    pub folder_key_encrypted: String,
    /// Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing.
    pub ipns_private_key_encrypted: String,
    /// Creation timestamp (Unix ms).
    pub created_at: u64,
    /// Last modification timestamp (Unix ms).
    pub modified_at: u64,
}

/// Slim file reference stored in folder metadata.
/// Points to a file's own IPNS record instead of embedding all file data inline.
/// Matches TypeScript `FilePointer` from `@cipherbox/crypto/file/types.ts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FilePointer {
    /// UUID for internal reference.
    pub id: String,
    /// File name (plaintext, since folder metadata is encrypted).
    pub name: String,
    /// IPNS name of the file's own metadata record.
    pub file_meta_ipns_name: String,
    /// Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
    /// Present for files created after the random-key migration. Absent for legacy files
    /// whose IPNS key is derived deterministically via HKDF.
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub ipns_private_key_encrypted: Option<String>,
    /// Creation timestamp (Unix ms).
    pub created_at: u64,
    /// Last modification timestamp (Unix ms).
    pub modified_at: u64,
}

/// A child entry can be either a folder or a file pointer.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
pub enum FolderChild {
    /// A subfolder entry.
    Folder(FolderEntry),
    /// A file pointer referencing a per-file IPNS record.
    File(FilePointer),
}

/// Decrypted folder metadata structure (v2 schema with per-file IPNS pointers).
/// The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
/// Children can be FolderEntry (subfolder) or FilePointer (slim IPNS reference).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FolderMetadata {
    /// Schema version (always "v2").
    pub version: String,
    /// Folders and file pointers in this folder.
    pub children: Vec<FolderChild>,
}

/// Encrypt folder metadata with AES-256-GCM.
///
/// JSON serializes the metadata, then seals with AES-GCM.
/// Returns the sealed bytes: IV (12) || ciphertext || tag (16).
pub fn encrypt_folder_metadata(
    metadata: &FolderMetadata,
    folder_key: &[u8; 32],
) -> Result<Vec<u8>, FolderError> {
    let mut json = serde_json::to_vec(metadata).map_err(|_| FolderError::SerializationFailed)?;
    let result = aes::seal_aes_gcm(&json, folder_key).map_err(FolderError::EncryptionFailed);
    json.zeroize();
    result
}

/// Decrypt folder metadata from AES-256-GCM sealed bytes.
///
/// Unseals, then JSON deserializes to FolderMetadata.
/// Rejects metadata with version other than "v2".
pub fn decrypt_folder_metadata(
    sealed: &[u8],
    folder_key: &[u8; 32],
) -> Result<FolderMetadata, FolderError> {
    let mut json = aes::unseal_aes_gcm(sealed, folder_key).map_err(FolderError::EncryptionFailed)?;

    // Parse as generic JSON to check version field
    let value: serde_json::Value =
        serde_json::from_slice(&json).map_err(|e| {
            log::error!("JSON parse failed: {}", e);
            json.zeroize();
            FolderError::DeserializationFailed
        })?;

    let version = value.get("version").and_then(|v| v.as_str());
    if version != Some("v2") {
        log::error!(
            "Unsupported folder metadata version: {:?} (only v2 is supported)",
            version
        );
        json.zeroize();
        return Err(FolderError::DeserializationFailed);
    }

    let result: Result<FolderMetadata, _> = serde_json::from_value(value).map_err(|e| {
        log::error!("V2 metadata deserialization failed: {}", e);
        FolderError::DeserializationFailed
    });

    json.zeroize();
    result
}

/// Default encryption mode for FileMetadata: "GCM".
fn default_encryption_mode() -> String {
    "GCM".to_string()
}

/// A single past version of a file.
/// Stores full crypto context for independent decryption.
/// Matches TypeScript `VersionEntry` from `@cipherbox/crypto/file/types.ts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VersionEntry {
    /// IPFS CID of the encrypted file content for this version.
    pub cid: String,
    /// Hex-encoded ECIES-wrapped AES-256 key for decrypting this version.
    pub file_key_encrypted: String,
    /// Hex-encoded IV used for this version's encryption.
    pub file_iv: String,
    /// Original file size in bytes (before encryption).
    pub size: u64,
    /// When this version was created (Unix ms).
    pub timestamp: u64,
    /// Encryption mode used for this version.
    pub encryption_mode: String,
}

/// Decrypted per-file metadata structure.
/// Stored as an encrypted blob in the file's own IPNS record.
/// Encrypted with the parent folder's folderKey (NOT the file's own key).
/// Matches TypeScript `FileMetadata` from `@cipherbox/crypto/file/types.ts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FileMetadata {
    /// Schema version.
    pub version: String,
    /// IPFS CID of the encrypted file content.
    pub cid: String,
    /// Hex-encoded ECIES-wrapped AES-256 key for decrypting file.
    pub file_key_encrypted: String,
    /// Hex-encoded IV used for file encryption.
    pub file_iv: String,
    /// Original file size in bytes (before encryption).
    pub size: u64,
    /// MIME type of the original file.
    pub mime_type: String,
    /// Encryption mode (optional for backward compat; defaults to "GCM").
    #[serde(default = "default_encryption_mode")]
    pub encryption_mode: String,
    /// Creation timestamp (Unix ms).
    pub created_at: u64,
    /// Last modification timestamp (Unix ms).
    pub modified_at: u64,
    /// Past versions of this file (newest first). None if no versions exist.
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub versions: Option<Vec<VersionEntry>>,
}

/// Encrypt file metadata with AES-256-GCM.
///
/// JSON serializes the metadata, then seals with AES-GCM.
/// Uses the parent folder's folderKey for encryption.
/// Returns the sealed bytes: IV (12) || ciphertext || tag (16).
pub fn encrypt_file_metadata(
    metadata: &FileMetadata,
    folder_key: &[u8; 32],
) -> Result<Vec<u8>, FolderError> {
    let mut json = serde_json::to_vec(metadata).map_err(|_| FolderError::SerializationFailed)?;
    let result = aes::seal_aes_gcm(&json, folder_key).map_err(FolderError::EncryptionFailed);
    json.zeroize();
    result
}

/// Decrypt file metadata from AES-256-GCM sealed bytes.
///
/// Uses the parent folder's folderKey for decryption.
/// Unseals, then JSON deserializes to FileMetadata.
pub fn decrypt_file_metadata(
    sealed: &[u8],
    folder_key: &[u8; 32],
) -> Result<FileMetadata, FolderError> {
    let mut json = aes::unseal_aes_gcm(sealed, folder_key).map_err(FolderError::EncryptionFailed)?;
    let result = serde_json::from_slice(&json).map_err(|_| FolderError::DeserializationFailed);
    json.zeroize();
    result
}

//! Authentication operations via the CipherBox backend API.
//!
//! Provides login, refresh, logout, and vault operations.

use crate::client::ApiClient;
use crate::error::ApiError;
use crate::types::*;

/// Log in to the CipherBox backend.
///
/// POST /auth/login with Web3Auth id_token and secp256k1 public key.
/// Returns access and refresh tokens.
pub async fn login(client: &ApiClient, request: &LoginRequest) -> Result<LoginResponse, ApiError> {
    let resp = client.post("/auth/login", request).await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::AuthFailed(format!(
            "Login failed ({}): {}",
            status, body
        )));
    }

    resp.json::<LoginResponse>()
        .await
        .map_err(|e| ApiError::DeserializationFailed(format!("Login response: {}", e)))
}

/// Refresh the access token using a refresh token.
///
/// POST /auth/refresh with the current refresh token.
/// Returns new access and refresh tokens (rotation).
pub async fn refresh(
    client: &ApiClient,
    request: &RefreshRequest,
) -> Result<RefreshResponse, ApiError> {
    let resp = client.post("/auth/refresh", request).await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::AuthFailed(format!(
            "Refresh failed ({}): {}",
            status, body
        )));
    }

    resp.json::<RefreshResponse>()
        .await
        .map_err(|e| ApiError::DeserializationFailed(format!("Refresh response: {}", e)))
}

/// Log out from the CipherBox backend.
///
/// POST /auth/logout (authenticated). Best-effort -- errors are logged
/// but not propagated (matches web app pattern).
pub async fn logout(client: &ApiClient) -> Result<(), ApiError> {
    let resp = client.authenticated_post("/auth/logout", &()).await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        log::warn!("Logout returned non-success ({}): {}", status, body);
    }

    Ok(())
}

/// Fetch the current user's vault.
///
/// GET /vault returns the root IPNS name and TEE keys.
pub async fn get_vault(client: &ApiClient) -> Result<VaultResponse, ApiError> {
    let resp = client.authenticated_get("/vault").await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("Get vault failed: {}", body),
        });
    }

    resp.json::<VaultResponse>()
        .await
        .map_err(|e| ApiError::DeserializationFailed(format!("Vault response: {}", e)))
}

/// Initialize a new user's vault.
///
/// POST /vault/init with the owner's public key and root IPNS name.
pub async fn init_vault(
    client: &ApiClient,
    request: &InitVaultRequest,
) -> Result<(), ApiError> {
    let resp = client.authenticated_post("/vault/init", request).await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("Init vault failed: {}", body),
        });
    }

    Ok(())
}

//! IPFS content operations via the CipherBox backend API.
//!
//! Provides fetching encrypted file content, uploading encrypted files,
//! and unpinning content. Content is always encrypted -- the backend
//! never sees plaintext.

use crate::client::ApiClient;
use crate::error::ApiError;
use crate::types::{UnpinRequest, UploadResponse};

/// Fetch encrypted file content from IPFS via the backend.
///
/// GET /ipfs/{cid} returns raw encrypted bytes (application/octet-stream).
pub async fn fetch_content(client: &ApiClient, cid: &str) -> Result<Vec<u8>, ApiError> {
    let resp = client
        .authenticated_get(&format!("/ipfs/{}", cid))
        .await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPFS fetch failed: {}", body),
        });
    }

    let bytes = resp.bytes().await.map_err(|e| {
        ApiError::DeserializationFailed(format!("Failed to read IPFS response: {}", e))
    })?;
    Ok(bytes.to_vec())
}

/// Upload encrypted file content to IPFS via the backend.
///
/// POST /ipfs/upload with multipart form data. Returns CID string.
pub async fn upload_content(client: &ApiClient, data: &[u8]) -> Result<String, ApiError> {
    use reqwest::multipart;

    let part = multipart::Part::bytes(data.to_vec())
        .file_name("encrypted")
        .mime_str("application/octet-stream")
        .map_err(|e| {
            ApiError::DeserializationFailed(format!("Failed to create multipart part: {}", e))
        })?;

    let form = multipart::Form::new().part("file", part);

    let resp = client
        .authenticated_multipart_post("/ipfs/upload", form)
        .await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPFS upload failed: {}", body),
        });
    }

    let upload_resp: UploadResponse = resp.json().await.map_err(|e| {
        ApiError::DeserializationFailed(format!("Failed to parse upload response: {}", e))
    })?;

    Ok(upload_resp.cid)
}

/// Unpin content from IPFS via the backend.
///
/// POST /ipfs/unpin with `{ cid }`. Fire-and-forget on delete
/// (matches web app pattern -- 404 treated as success).
pub async fn unpin_content(client: &ApiClient, cid: &str) -> Result<(), ApiError> {
    let resp = client
        .authenticated_post("/ipfs/unpin", &UnpinRequest { cid })
        .await?;

    // 404 is success (already unpinned -- idempotent behavior)
    if resp.status().as_u16() == 404 || resp.status().is_success() {
        Ok(())
    } else {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        Err(ApiError::ApiResponse {
            status,
            message: format!("IPFS unpin failed: {}", body),
        })
    }
}

//! Recycle bin metadata types and encryption.
//!
//! Mirrors the TypeScript `RecycleBinMetadata` and `BinEntry` types from
//! `@cipherbox/crypto` for cross-platform compatibility. Uses ECIES
//! (same as DeviceRegistry) for encryption -- the user's secp256k1
//! publicKey encrypts, privateKey decrypts.

use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::folder::{FilePointer, FolderEntry};

#[derive(Debug, Error)]
pub enum BinError {
    #[error("Bin metadata encryption failed")]
    EncryptionFailed,
    #[error("Bin metadata decryption failed")]
    DecryptionFailed,
    #[error("Bin metadata serialization failed")]
    SerializationFailed,
    #[error("Bin metadata deserialization failed")]
    DeserializationFailed,
    #[error("Bin metadata validation failed: {0}")]
    ValidationFailed(String),
}

/// Top-level recycle bin metadata structure.
/// Encrypted as a whole blob via ECIES with the user's secp256k1 publicKey.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RecycleBinMetadata {
    pub version: String,
    pub sequence_number: u64,
    pub entries: Vec<BinEntry>,
}

/// A single item in the recycle bin.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BinEntry {
    pub id: String,
    pub item_type: BinItemType,
    pub name: String,
    pub original_parent_ipns_name: String,
    pub original_path: String,
    pub deleted_at: u64,
    pub size: u64,
    pub mime_type: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub content_cid: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub content_size: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub version_cids: Option<Vec<VersionCidEntry>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub file_pointer: Option<FilePointer>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub folder_entry: Option<FolderEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VersionCidEntry {
    pub cid: String,
    pub size: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum BinItemType {
    File,
    Folder,
}

/// Encrypt bin metadata with ECIES using user's secp256k1 public key.
///
/// JSON-serializes the metadata, then encrypts the entire blob with ECIES.
/// Cross-compatible with TypeScript `encryptBinMetadata` from @cipherbox/crypto.
pub fn encrypt_bin_metadata(
    metadata: &RecycleBinMetadata,
    user_public_key: &[u8],
) -> Result<Vec<u8>, BinError> {
    let json = serde_json::to_vec(metadata)
        .map_err(|_| BinError::SerializationFailed)?;
    cipherbox_crypto::ecies::wrap_key(&json, user_public_key)
        .map_err(|_| BinError::EncryptionFailed)
}

/// Decrypt bin metadata with ECIES using user's secp256k1 private key.
pub fn decrypt_bin_metadata(
    ciphertext: &[u8],
    user_private_key: &[u8],
) -> Result<RecycleBinMetadata, BinError> {
    let plaintext = cipherbox_crypto::ecies::unwrap_key(ciphertext, user_private_key)
        .map_err(|_| BinError::DecryptionFailed)?;
    let metadata: RecycleBinMetadata = serde_json::from_slice(&plaintext)
        .map_err(|_| BinError::DeserializationFailed)?;
    if metadata.version != "v1" {
        return Err(BinError::ValidationFailed(
            format!("Unsupported bin metadata version: {}", metadata.version),
        ));
    }
    Ok(metadata)
}

/// Create a new empty RecycleBinMetadata.
pub fn empty_bin_metadata() -> RecycleBinMetadata {
    RecycleBinMetadata {
        version: "v1".to_string(),
        sequence_number: 0,
        entries: vec![],
    }
}

//! IPNS resolution and publishing via the CipherBox backend API.
//!
//! Resolves IPNS names to their current CID and sequence number,
//! and publishes signed IPNS records.

use crate::client::ApiClient;
use crate::error::ApiError;
use crate::types::{IpnsPublishRequest, IpnsResolveResponse, PublishResult};

/// Resolve an IPNS name to its current CID via the backend.
///
/// GET /ipns/resolve?ipnsName={name}
/// Returns the CID and sequence number of the current IPNS record.
pub async fn resolve_ipns(
    client: &ApiClient,
    ipns_name: &str,
) -> Result<IpnsResolveResponse, ApiError> {
    let path = format!(
        "/ipns/resolve?ipnsName={}",
        urlencoding::encode(ipns_name)
    );
    let resp = client.authenticated_get(&path).await?;

    if resp.status().as_u16() == 404 {
        return Err(ApiError::IpnsNotFound(ipns_name.to_string()));
    }

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPNS resolve failed: {}", body),
        });
    }

    resp.json::<IpnsResolveResponse>()
        .await
        .map_err(|e| ApiError::DeserializationFailed(format!("IPNS resolve response: {}", e)))
}

/// Publish a signed IPNS record via the backend.
///
/// POST /ipns/publish with the signed record. The backend relays
/// to the delegated routing service and tracks the folder for TEE republishing.
///
/// Returns `PublishResult::Success` on 2xx, `PublishResult::Conflict`
/// on 409 (another device published a higher sequence), or `Err` on
/// other errors.
pub async fn publish_ipns(
    client: &ApiClient,
    request: &IpnsPublishRequest,
) -> Result<PublishResult, ApiError> {
    let resp = client
        .authenticated_post("/ipns/publish", request)
        .await?;

    if resp.status().as_u16() == 409 {
        // Parse conflict response body: { currentSequenceNumber: "..." }
        let body: serde_json::Value = resp.json().await.map_err(|e| {
            ApiError::DeserializationFailed(format!("409 Conflict but failed to parse body: {}", e))
        })?;
        let current_seq = body["currentSequenceNumber"]
            .as_str()
            .ok_or_else(|| {
                ApiError::DeserializationFailed(format!(
                    "409 Conflict but missing currentSequenceNumber in response: {}",
                    body
                ))
            })?
            .to_string();
        return Ok(PublishResult::Conflict {
            current_sequence_number: current_seq,
        });
    }

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPNS publish failed: {}", body),
        });
    }

    Ok(PublishResult::Success)
}

//! Typed HTTP client for CipherBox API.
//!
//! Provides async functions for all CipherBox API endpoints
//! used by the desktop app: auth, IPFS, IPNS, vault operations.
//! Mirrors @cipherbox/api-client TypeScript package.

pub mod auth;
pub mod client;
pub mod error;
pub mod ipfs;
pub mod ipns;
pub mod types;

pub use client::ApiClient;
pub use error::ApiError;
pub use types::*;

//! Vault key blob v2 format: binary envelope for ECIES-wrapped rootFolderKey.
//!
//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key
//!
//! This is a key-only blob -- folder metadata is stored separately at
//! the root folder's own IPNS name using standard v1 JSON format.

/// Version byte for v2 format.
pub const BLOB_V2_VERSION: u8 = 0x02;

/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
///
/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
pub fn detect_blob_version(blob: &[u8]) -> u8 {
    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
        2
    } else {
        1
    }
}

/// Serialize a vault key blob v2.
///
/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key`
pub fn serialize_vault_blob_v2(encrypted_root_folder_key: &[u8]) -> Result<Vec<u8>, String> {
    if encrypted_root_folder_key.is_empty() {
        return Err("Encrypted key must not be empty for v2 blob".into());
    }
    if encrypted_root_folder_key.len() > u16::MAX as usize {
        return Err(format!(
            "Encrypted key too long for v2 blob ({} bytes, max {})",
            encrypted_root_folder_key.len(),
            u16::MAX
        ));
    }
    let key_len = encrypted_root_folder_key.len() as u16;
    let mut result = Vec::with_capacity(3 + encrypted_root_folder_key.len());
    result.push(BLOB_V2_VERSION);
    result.push((key_len >> 8) as u8);
    result.push((key_len & 0xff) as u8);
    result.extend_from_slice(encrypted_root_folder_key);
    Ok(result)
}

/// Deserialize a vault key blob v2 to extract the encrypted rootFolderKey.
///
/// Returns borrowed slice into the original blob for zero-copy parsing.
pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<&[u8], String> {
    if blob.len() < 3 {
        return Err(format!(
            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
            blob.len()
        ));
    }
    if blob[0] != BLOB_V2_VERSION {
        return Err("Not a v2 vault blob".into());
    }
    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
    if key_len == 0 {
        return Err("Invalid v2 blob: encrypted key length must be > 0".into());
    }
    if blob.len() < 3 + key_len {
        return Err(format!(
            "Vault blob too short for key (expected {} bytes, have {})",
            key_len,
            blob.len() - 3
        ));
    }
    Ok(&blob[3..3 + key_len])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_round_trip() {
        let key = vec![0xAA; 129];
        let blob = serialize_vault_blob_v2(&key).unwrap();
        let decoded_key = deserialize_vault_blob_v2(&blob).unwrap();
        assert_eq!(decoded_key, key.as_slice());
    }

    #[test]
    fn test_detect_v2() {
        let blob = serialize_vault_blob_v2(&[0; 129]).unwrap();
        assert_eq!(detect_blob_version(&blob), 2);
    }

    #[test]
    fn test_detect_v1() {
        let v1 = b"{\"iv\":\"abc\",\"data\":\"def\"}";
        assert_eq!(detect_blob_version(v1), 1);
    }

    #[test]
    fn test_deserialize_v1_blob_errors() {
        let v1 = b"{\"iv\":\"abc\"}";
        assert!(deserialize_vault_blob_v2(v1).is_err());
    }

    #[test]
    fn test_deserialize_empty_blob_errors() {
        assert!(deserialize_vault_blob_v2(&[]).is_err());
    }

    #[test]
    fn test_deserialize_short_blob_errors() {
        assert!(deserialize_vault_blob_v2(&[0x02, 0x00]).is_err());
    }

    #[test]
    fn test_key_len_overflow_errors() {
        let blob = vec![0x02, 0x03, 0xE8, 0, 0, 0, 0, 0];
        assert!(deserialize_vault_blob_v2(&blob).is_err());
    }

    #[test]
    fn test_header_format() {
        let key = vec![0xBB; 129];
        let blob = serialize_vault_blob_v2(&key).unwrap();
        assert_eq!(blob[0], 0x02);
        assert_eq!(blob[1], 0x00); // 129 >> 8 = 0
        assert_eq!(blob[2], 0x81); // 129 & 0xFF = 0x81
        assert_eq!(&blob[3..], key.as_slice());
        assert_eq!(blob.len(), 3 + 129);
    }

    // Cross-platform test vector: MUST match TypeScript vault-blob-vectors.test.ts
    #[test]
    fn test_cross_platform_vector() {
        let mut key = vec![0xAA];
        for i in 0u8..128 {
            key.push(i);
        }
        assert_eq!(key.len(), 129);

        let blob = serialize_vault_blob_v2(&key).unwrap();

        assert_eq!(blob[0], 0x02);
        assert_eq!(blob[1], 0x00);
        assert_eq!(blob[2], 0x81); // 129
        assert_eq!(blob.len(), 3 + 129);

        let blob_hex = hex::encode(&blob);
        let expected_hex = concat!(
            "02",   // version byte
            "0081", // key_len = 129
            "aa",   // key[0]
            "000102030405060708090a0b0c0d0e0f", // key[1..16]
            "101112131415161718191a1b1c1d1e1f", // key[17..32]
            "202122232425262728292a2b2c2d2e2f", // key[33..48]
            "303132333435363738393a3b3c3d3e3f", // key[49..64]
            "404142434445464748494a4b4c4d4e4f", // key[65..80]
            "505152535455565758595a5b5c5d5e5f", // key[81..96]
            "606162636465666768696a6b6c6d6e6f", // key[97..112]
            "707172737475767778797a7b7c7d7e7f", // key[113..128]
        );
        assert_eq!(blob_hex, expected_hex);

        let dk = deserialize_vault_blob_v2(&blob).unwrap();
        assert_eq!(dk, key.as_slice());
    }

    #[test]
    fn test_cross_platform_minimal_vector() {
        let key = vec![0xFF];
        let blob = serialize_vault_blob_v2(&key).unwrap();
        let expected_hex = "020001ff";
        assert_eq!(hex::encode(&blob), expected_hex);

        let dk = deserialize_vault_blob_v2(&blob).unwrap();
        assert_eq!(dk, &[0xFF]);
    }

    #[test]
    fn test_key_too_long_for_u16() {
        let key = vec![0xAA; 65536];
        let result = serialize_vault_blob_v2(&key);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("too long"));
    }

    #[test]
    fn test_zero_length_key_rejected() {
        let result = serialize_vault_blob_v2(&[]);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("must not be empty"));

        let blob = vec![0x02, 0x00, 0x00];
        assert!(deserialize_vault_blob_v2(&blob).is_err());
    }
}

